 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find each maximal straight diagonal run (length >= 2), then extend it
    # from the end whose outward ray has the longest uninterrupted background.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue  # Not the first cell of this diagonal run.
                run = [(r, c)]
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # Count clear background cells beyond each endpoint.
                br, bc = run[0][0] - dr, run[0][1] - dc
                back = []
                while 0 <= br < h and 0 <= bc < w and grid[br][bc] == bg:
                    back.append((br, bc))
                    br -= dr
                    bc -= dc
                fr, fc = run[-1][0] + dr, run[-1][1] + dc
                forward = []
                while 0 <= fr < h and 0 <= fc < w and grid[fr][fc] == bg:
                    forward.append((fr, fc))
                    fr += dr
                    fc += dc
                extension = forward if len(forward) > len(back) else back
                for er, ec in extension:
                    out[er][ec] = color
    return out
